UPDATE sales_order_item
SET
shipped_qty = shipped_qty + #{baseShippedQty},
version = version + 1,
updated_at =
CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by = #{updatedBy}
WHERE sales_order_item_id = #{salesOrderItemId}
AND version = #{version}
AND shipped_qty + #{baseShippedQty} <= base_ordered_qty

UPDATE sales_order_item
SET
shipped_qty = shipped_qty - #{baseShippedQty},
version = version + 1,
updated_at =
CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
),
updated_by = #{updatedBy}
WHERE sales_order_item_id = #{salesOrderItemId}
AND version = #{version}
AND shipped_qty >= #{baseShippedQty}

mapper.select:
SELECT COUNT(*)
FROM warehouse w
WHERE w.warehouse_id = #{warehouseId}
AND w.company_id = #{companyId}
AND w.use_yn = 'Y'

SELECT COUNT(*)
FROM lot_stock ls
JOIN lot l
ON l.lot_id = ls.lot_id
WHERE ls.company_id = #{companyId}
AND ls.warehouse_id = #{warehouseId}
AND ls.lot_id = #{lotId}
AND l.product_id = #{productId}
AND ls.quantity >= #{baseLotQty}

