UPDATE outbound
SET
    sales_order_id = #{salesOrderId},
    warehouse_id = #{warehouseId},
    updated_at = CAST(
        SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
        AS TIMESTAMP
    ),
    updated_by = #{updatedBy}
WHERE company_id = #{companyId}
AND outbound_id = #{outboundId}
AND status = 'DRAFT'

mapper.delete:
DELETE FROM outbound_item oi
WHERE oi.outbound_id = #{outboundId}
AND EXISTS (
    SELECT 1
    FROM outbound ob
    WHERE ob.outbound_id = oi.outbound_id
    AND ob.company_id = #{companyId}
    AND ob.status = 'DRAFT'
)

DELETE FROM outbound
WHERE company_id = #{companyId}
AND outbound_id = #{outboundId}
AND status = 'DRAFT'

mapper.update:
UPDATE lot_stock
SET quantity = quantity - #{baseLotQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND lot_id = #{lotId}
AND quantity >= #{baseLotQty}
AND EXISTS (
SELECT 1
FROM lot l
WHERE l.lot_id = lot_stock.lot_id
AND l.company_id = #{companyId}
AND l.product_id = #{productId}
)

UPDATE stock
SET quantity = quantity - #{baseShippedQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND product_id = #{productId}
AND quantity >= #{baseShippedQty}

UPDATE lot_stock
SET quantity = quantity + #{baseLotQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND lot_id = #{lotId}
AND EXISTS (
SELECT 1
FROM lot l
WHERE l.lot_id = lot_stock.lot_id
AND l.company_id = #{companyId}
AND l.product_id = #{productId}
)

UPDATE stock
SET quantity = quantity + #{baseShippedQty}
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND product_id = #{productId}
